package com.cqutcm.biomed.controller;import com.cqutcm.biomed.service.*;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/improvement-recommendations") public class ImprovementRecommendationController{private final AuthService auth;private final ImprovementRecommendationService service;public ImprovementRecommendationController(AuthService a,ImprovementRecommendationService s){auth=a;service=s;}@GetMapping("/evaluation/{id}")public Map<String,Object>list(@PathVariable String id,@RequestHeader(value="Authorization",required=false)String t){return Map.of("items",service.list(id,auth.requireActor(t)));}@PostMapping("/{id}/accept")public Map<String,Object>accept(@PathVariable String id,@RequestBody(required=false)Map<String,Object>b,@RequestHeader(value="Authorization",required=false)String t){return service.accept(id,b==null?Map.of():b,auth.requireActor(t));}@PutMapping("/{id}/ignore")public Map<String,Object>ignore(@PathVariable String id,@RequestHeader(value="Authorization",required=false)String t){service.ignore(id,auth.requireActor(t));return Map.of("message","recommendation ignored");}}
